INSERT INTO public.test_questions (id, test_id, number, question_type, question_text, max_points, key_answer, key_answer_embedding, embedding_model, created_at) VALUES ('4fe66368-c459-5c09-8757-427e1e89be7b', '8eb3d2a9-53f5-5d68-bd3c-0016fa1cd804', 1, 'calculation', 'Hitung limit x->2 dari (x^2 - 4)/(x - 2).', 25, 'Faktorkan pembilang menjadi (x-2)(x+2), sederhanakan menjadi x+2, lalu substitusi x=2 sehingga hasilnya 4.', NULL, 'gemini-embedding-001', '2026-05-12 09:25:38.656532+00');
INSERT INTO public.test_questions (id, test_id, number, question_type, question_text, max_points, key_answer, key_answer_embedding, embedding_model, created_at) VALUES ('f6412190-225a-5588-b35a-781633eaac30', '8eb3d2a9-53f5-5d68-bd3c-0016fa1cd804', 2, 'calculation', 'Tentukan turunan f(x) = 3x^3 - 5x^2 + 2x - 7.', 25, 'f''(x) = 9x^2 - 10x + 2 menggunakan aturan pangkat untuk tiap suku.', NULL, 'gemini-embedding-001', '2026-05-12 09:25:38.656532+00');
INSERT INTO public.test_questions (id, test_id, number, question_type, question_text, max_points, key_answer, key_answer_embedding, embedding_model, created_at) VALUES ('0ec486c8-7025-5d85-9b4f-c7ac2a30065a', '8eb3d2a9-53f5-5d68-bd3c-0016fa1cd804', 3, 'calculation', 'Hitung integral tentu dari 0 sampai 2 untuk fungsi 2x + 1.', 25, 'Antiturunan x^2 + x, dievaluasi 0 sampai 2 menghasilkan (4 + 2) - 0 = 6.', NULL, 'gemini-embedding-001', '2026-05-12 09:25:38.656532+00');
