INSERT INTO public.test_questions (id, test_id, number, question_type, question_text, max_points, key_answer, key_answer_embedding, embedding_model, created_at) VALUES ('b7ff0377-0598-4f27-a074-4fb7b573bd26', 'bec42134-532a-4b94-861e-0a0caa212f26', 10, 'essay', 'Hitung ∫ dari 1 sampai e (ln x)/x dx menggunakan metode substitusi.', 12, 'Misalkan u = ln x, du = dx/x. Batasnya: x = 1 → u = 0 dan x = e → u = 1. Jadi ∫₀¹ u du = [u²/2]₀¹ = 1/2.', NULL, 'gemini-embedding-001', '2026-10-13 09:28:21.251299+00');
INSERT INTO public.test_questions (id, test_id, number, question_type, question_text, max_points, key_answer, key_answer_embedding, embedding_model, created_at) VALUES ('d828b11a-ec17-4f58-a64b-2edba7491359', 'bec42134-532a-4b94-861e-0a0caa212f26', 14, 'calculation', 'Buktikan bahwa persamaan x³ + x − 1 = 0 memiliki tepat satu akar real, dan akar tersebut terletak pada interval (0, 1).', 15, 'Ada akar: f(x) = x³ + x − 1 adalah polinom, jadi kontinu di [0, 1]. f(0) = −1 < 0 dan f(1) = 1 > 0. Menurut Teorema Nilai Antara, ada c di (0, 1) dengan f(c) = 0.
