INSERT INTO public.student_complaints (id, student_id, student_test_id, test_answer_id, complaint, teacher_response, resolved_at, ai_summary, ai_recommendation, status, created_at) VALUES ('6fa5c469-1da8-500d-a4b0-e5f9229c5898', '9b3dd4f8-721d-59b8-b307-32910e3731c1', '676a8f2e-3a73-5fbc-b1f2-ae1d7a1628f2', '5539be59-8957-522a-9680-cba14294faed', 'Saya sudah menuliskan contoh penggunaannya di halaman kedua, sepertinya tidak terbaca.', NULL, NULL, 'Mahasiswa merasa langkah pengerjaan sudah benar dan meminta peninjauan ulang.', 'Nilai AI sudah sesuai rubrik; keberatan kurang kuat.', 'pending', '2026-09-15 09:25:38.656532+00');
INSERT INTO public.student_complaints (id, student_id, student_test_id, test_answer_id, complaint, teacher_response, resolved_at, ai_summary, ai_recommendation, status, created_at) VALUES ('828ae3fa-d1f9-5af5-aaa6-319310ac38c0', 'a7393ffa-91a0-527f-b0be-0565d243c9e8', '3be97f3a-49f5-59e0-aa5e-7692fd1109c7', '4e4b55f8-06cb-5e82-b9c2-7cff60b90e79', 'Saya sudah menuliskan contoh penggunaannya di halaman kedua, sepertinya tidak terbaca.', NULL, NULL, 'Mahasiswa merasa langkah pengerjaan sudah benar dan meminta peninjauan ulang.', 'Pertimbangkan menambah 3-5 poin pada kriteria langkah.', 'pending', '2026-09-15 09:25:38.656532+00');
INSERT INTO public.student_complaints (id, student_id, student_test_id, test_answer_id, complaint, teacher_response, resolved_at, ai_summary, ai_recommendation, status, created_at) VALUES ('76d5b2d7-9988-519e-ad71-17920d1e204d', 'd276e412-0d4d-50b3-8770-d5eab4f0b373', 'ef2779bf-e6ba-59e0-9ffb-87867ea7fb9f', '9e047c15-719b-5b14-8cbf-190a3352d09b', 'Pak/Bu, menurut saya langkah saya di soal ini sudah benar, hanya salah hitung di akhir. Mohon ditinjau ulang.', 'Setelah ditinjau, langkah Anda benar. Nilai disesuaikan.', '2026-09-17 09:25:38.656532+00', 'Mahasiswa merasa langkah pengerjaan sudah benar dan meminta peninjauan ulang.', 'Pertimbangkan menambah 3-5 poin pada kriteria langkah.', 'accepted', '2026-09-15 09:25:38.656532+00');
INSERT INTO public.student_complaints (id, student_id, student_test_id, test_answer_id, complaint, teacher_response, resolved_at, ai_summary, ai_recommendation, status, created_at) VALUES ('27e26057-36ce-5d26-8912-9de25cc37dcf', 'fb994b71-74e6-54bb-a0f7-8cb0b46875fe', '45f816c3-0653-595d-b330-c85a2b55bc88', 'dea18439-c7b8-52c9-91cf-20a409fb71b3', 'Tulisan saya di bagian akhir mungkin kurang jelas, tapi hasilnya sudah saya tulis 4.', 'Setelah ditinjau, langkah Anda benar. Nilai disesuaikan.', '2026-09-17 09:25:38.656532+00', 'Mahasiswa merasa langkah pengerjaan sudah benar dan meminta peninjauan ulang.', 'Nilai AI sudah sesuai rubrik; keberatan kurang kuat.', 'accepted', '2026-09-15 09:25:38.656532+00');
INSERT INTO public.student_complaints (id, student_id, student_test_id, test_answer_id, complaint, teacher_response, resolved_at, ai_summary, ai_recommendation, status, created_at) VALUES ('378231f6-5cca-56a2-bd97-ad060801b066', '18485dd3-db25-5bc4-8986-58dceb753484', 'd964be69-f9c5-5565-a280-0ec67328e746', '94e92ef4-25ae-52b4-a740-cc781d9b198b', 'Pak/Bu, menurut saya langkah saya di soal ini sudah benar, hanya salah hitung di akhir. Mohon ditinjau ulang.', 'Jawaban belum memenuhi kriteria rubrik, nilai tetap.', '2026-09-17 09:25:38.656532+00', 'Mahasiswa merasa langkah pengerjaan sudah benar dan meminta peninjauan ulang.', 'Pertimbangkan menambah 3-5 poin pada kriteria langkah.', 'rejected', '2026-09-15 09:25:38.656532+00');
