INSERT INTO public.test_pages (id, student_test_id, page_no, image_path, ocr_result, status, error, updated_at, created_at) VALUES ('96dada4c-d549-44fe-9c83-6ab62c07f0b1', '20e562c8-a4a3-46f1-8d2e-2fe7c2b24373', 1, '26001271-e8bb-5f12-8b14-0ab1480a3865/7c1f42fd-b308-4449-bedc-10f9f336192d/861f61c0-58ab-5b9d-9f81-3fba4f661afd-001.jpg', '[{"bbox": [421, 169, 568, 226], "html": "<h1>Ke mana?</h1>", "text": "Ke mana?", "label": "SectionHeader"}, {"bbox": [320, 247, 668, 271], "html": "<p>Cari destinasi, lihat kepadatannya, lalu pilih waktu kunjungan yang paling nyaman.</p>", "text": "Cari destinasi, lihat kepadatannya, lalu pilih waktu kunjungan yang paling nyaman.", "label": "Text"}, {"bbox": [283, 327, 463, 355], "html": "<img data-bbox=\"903 503 957 546\" src=\"e3f8612927870f2e0f9f5989e6dd3064_img.jpg\"/> Destinasi, kota, atau taman nasional...", "text": "Destinasi, kota, atau taman nasional...", "label": "Text"}, {"bbox": [673, 330, 701, 353], "html": "<b>Cari</b>", "text": "Cari", "label": "Text"}, {"bbox": [287, 419, 348, 444], "html": "<img data-bbox=\"916 645 957 683\" src=\"17413706fd4997a1a4bdf85c6864eee1_img.jpg\"/> Destinasi", "text": "Destinasi", "label": "Text"}, {"bbox": [369, 419, 414, 444], "html": "<img data-bbox=\"1177 645 1219 683\" src=\"faf942dc3e59ce8eb64b4ac481eca7e0_img.jpg\"/> Hotel", "text": "Hotel", "label": "Text"}, {"bbox": [435, 419, 517, 444], "html": "<img data-bbox=\"1388 645 1433 683\" src=\"cf531ed27e91483460120fcc057b3901_img.jpg\"/> Tiket Pesawat", "text": "Tiket Pesawat", "label": "Text"}, {"bbox": [536, 419, 611, 444], "html": "<img data-bbox=\"1710 645 1752 683\" src=\"d3102649f02e825ddb76dc3de0190154_img.jpg\"/> Peta Wisata", "text": "Peta Wisata", "label": "Text"}, {"bbox": [629, 419, 703, 444], "html": "<img data-bbox=\"2007 645 2049 683\" src=\"4b7a79268f6ba26c1471d4232fffa85a_img.jpg\"/> Waktu Sepi", "text": "Waktu Sepi", "label": "Text"}, {"bbox": [146, 594, 384, 621], "html": "<h2>Dapatkan rekomendasi sesuai minat Anda</h2>", "text": "Dapatkan rekomendasi sesuai minat Anda", "label": "SectionHeader"}, {"bbox": [146, 634, 494, 658], "html": "<p>Masuk, pilih jenis destinasi yang Anda sukai, dan lihat pilihan yang dipersonalisasi.</p>", "text": "Masuk, pilih jenis destinasi yang Anda sukai, dan lihat pilihan yang dipersonalisasi.", "label": "Text"}, {"bbox": [791, 612, 830, 636], "html": "<b>Masuk</b>", "text": "Masuk", "label": "Text"}, {"bbox": [129, 771, 395, 810], "html": "<h2>Jelajahi berdasarkan jenis destinasi</h2>", "text": "Jelajahi berdasarkan jenis destinasi", "label": "SectionHeader"}, {"bbox": [129, 819, 417, 845], "html": "<p>Setiap destinasi dilengkapi kuota harian dan prediksi kepadatannya</p>", "text": "Setiap destinasi dilengkapi kuota harian dan prediksi kepadatannya", "label": "Text"}, {"bbox": [783, 819, 858, 843], "html": "<a href=\"#\">Lihat semua →</a>", "text": "Lihat semua →", "label": "Text"}, {"bbox": [133, 866, 307, 1000], "html": "<img alt=\"Photo: Top portion of a blue and white bus showing the roof and windows.\" src=\"c23a98f443a2fbc7b9a13380e5d38a8c_img.jpg\"/><div class=\"img-description\" style=\"border: 1px solid #ccc; padding: 10px;\"><p class=\"img-desc\">A close-up view of the upper part of a bus, featuring a white roof with a rectangular sign or light fixture and a row of blue-framed windows below.</p><div class=\"img-alt\">Photo: Top portion of a blue and white bus showing the roof and windows.</div></div>", "text": "A close-up view of the upper part of a bus, featuring a white roof with a rectangular sign or light fixture and a row of blue-framed windows below.\nPhoto: Top portion of a blue and white bus showing the roof and windows.", "label": "Picture"}, {"bbox": [316, 866, 489, 1000], "html": "<img alt=\"A photograph of a dense green forest with various trees and foliage.\" src=\"31cdb383e9cc2643a547f2500ed3cd08_img.jpg\"/><div class=\"img-description\" style=\"border: 1px solid #ccc; padding: 10px;\"><div class=\"img-alt\">A photograph of a dense green forest with various trees and foliage.</div></div>", "text": "A photograph of a dense green forest with various trees and foliage.", "label": "Picture"}, {"bbox": [500, 866, 670, 1000], "html": "<img alt=\"Photo: Front facade of a historic stone building with towers and spires.\" src=\"8d0979f8938b15f6c0ab58694e4e5fac_img.jpg\"/><div class=\"img-description\" style=\"border: 1px solid #ccc; padding: 10px;\"><p class=\"img-desc\">A photograph showing the symmetrical stone facade of a large building featuring arched windows, a central gable with a clock, and multiple tall spires and towers under a cloudy sky.</p><div class=\"img-alt\">Photo: Front facade of a historic stone building with towers and spires.</div></div>", "text": "A photograph showing the symmetrical stone facade of a large building featuring arched windows, a central gable with a clock, and multiple tall spires and towers under a cloudy sky.\nPhoto: Front facade of a historic stone building with towers and spires.", "label": "Picture"}, {"bbox": [679, 866, 853, 1000], "html": "<img alt=\"Dark blue rectangular bar on the left side of the slide.\" src=\"818eb5572c4d07d18323e822bb5ba791_img.jpg\"/><div class=\"img-description\" style=\"border: 1px solid #ccc; padding: 10px;\"><div class=\"img-alt\">Dark blue rectangular bar on the left side of the slide.</div></div>", "text": "Dark blue rectangular bar on the left side of the slide.", "label": "Picture"}]', 'success', NULL, '2026-10-13 13:57:20.991875+00', '2026-10-13 13:57:10.494726+00');
