INSERT INTO public.test_pages (id, student_test_id, page_no, image_path, ocr_result, status, error, updated_at, created_at) VALUES ('14eb631d-4eca-4c2f-8c2f-1505e85ccf7d', 'b51a68f5-f0c3-4b2f-8faf-290dd560f642', 1, '26001271-e8bb-5f12-8b14-0ab1480a3865/7c1f42fd-b308-4449-bedc-10f9f336192d/8373be95-8b4b-4c07-ac4a-fddeb4e09565-001.jpg', '[{"bbox": [60, 47, 373, 108], "html": "<p><math display=\"block\">1. \\lim_{x \\rightarrow 0} \\frac{\\sin 3x}{x} = 3</math></p>", "text": "1. \\lim_{x \\rightarrow 0} \\frac{\\sin 3x}{x} = 3", "label": "Equation"}, {"bbox": [53, 139, 728, 233], "html": "<p><math display=\"block\">2. f(x) = \\ln(x^2 + 1) \\quad 3x^2 - 3</math>\n<math display=\"block\">f''(x) = \\frac{2}{x^2 + 1} \\quad x - 1 \\quad x \\neq 1</math></p>", "text": "2. f(x) = \\ln(x^2 + 1) \\quad 3x^2 - 3\nf''(x) = \\frac{2}{x^2 + 1} \\quad x - 1 \\quad x \\neq 1", "label": "Equation"}, {"bbox": [60, 259, 436, 298], "html": "<p><math display=\"block\">3. \\int e^{2x} dx = 2e^{2x} + C</math></p>", "text": "3. \\int e^{2x} dx = 2e^{2x} + C", "label": "Equation"}, {"bbox": [56, 323, 297, 353], "html": "<p><math display=\"block\">4. f(x) = x^3 - 3x</math></p>", "text": "4. f(x) = x^3 - 3x", "label": "Equation"}, {"bbox": [103, 352, 531, 387], "html": "<p><math display=\"block\">f''(x) = 3x^2 - 3 = 3(x^2 - 1)</math></p>", "text": "f''(x) = 3x^2 - 3 = 3(x^2 - 1)", "label": "Equation"}, {"bbox": [105, 391, 556, 420], "html": "<p>titik kritis = <math>x = 1</math> dan <math>x = -1</math></p>", "text": "titik kritis = x = 1 dan x = -1", "label": "Text"}, {"bbox": [56, 448, 551, 482], "html": "<p>5. fungsi <math>f(x) = |x|</math> pada <math>x = 0</math></p>", "text": "5. fungsi f(x) = |x| pada x = 0", "label": "Text"}, {"bbox": [114, 480, 563, 511], "html": "<p>a). kontinu dan terdefinisikan</p>", "text": "a). kontinu dan terdefinisikan", "label": "Text"}, {"bbox": [58, 540, 673, 598], "html": "<p><math display=\"block\">6. \\lim_{x \\rightarrow 2} \\frac{x^2 - 4}{x - 2} \\Rightarrow \\frac{(x-2)(x+2)}{x-2} = x+2</math></p>", "text": "6. \\lim_{x \\rightarrow 2} \\frac{x^2 - 4}{x - 2} \\Rightarrow \\frac{(x-2)(x+2)}{x-2} = x+2", "label": "Equation"}, {"bbox": [62, 604, 356, 659], "html": "<p><math display=\"block\">\\rightarrow \\lim_{x \\rightarrow 2} x+2 \\Rightarrow 4</math></p>", "text": "\\rightarrow \\lim_{x \\rightarrow 2} x+2 \\Rightarrow 4", "label": "Equation"}, {"bbox": [45, 697, 303, 724], "html": "<p><math display=\"block\">7. f(x) = x \\cdot e^x</math></p>", "text": "7. f(x) = x \\cdot e^x", "label": "Equation"}, {"bbox": [106, 727, 401, 756], "html": "<p><math display=\"block\">f''(x) = x \\cdot e^x + e^x</math></p>", "text": "f''(x) = x \\cdot e^x + e^x", "label": "Equation"}, {"bbox": [105, 763, 295, 812], "html": "<p><math display=\"block\">f''(0) = 0 \\cdot f''1</math>\n<math display=\"block\">= 1</math></p>", "text": "f''(0) = 0 \\cdot f''1\n= 1", "label": "Equation"}, {"bbox": [463, 698, 654, 743], "html": "<p><math display=\"block\">8. \\int_0^\\pi \\sin x \\, dx</math></p>", "text": "8. \\int_0^\\pi \\sin x \\, dx", "label": "Equation"}, {"bbox": [469, 758, 617, 792], "html": "<p><math display=\"block\">= [-\\cos x]_0^\\pi</math></p>", "text": "= [-\\cos x]_0^\\pi", "label": "Equation"}, {"bbox": [469, 796, 628, 818], "html": "<p><math display=\"block\">= -(-1) - (1)</math></p>", "text": "= -(-1) - (1)", "label": "Equation"}, {"bbox": [471, 829, 519, 848], "html": "<p><math display=\"block\">= 0</math></p>", "text": "= 0", "label": "Equation"}]', 'success', NULL, '2026-10-14 10:33:49.331491+00', '2026-10-14 10:33:41.738423+00');
