INSERT INTO public.test_pages (id, student_test_id, page_no, image_path, ocr_result, status, error, updated_at, created_at) VALUES ('b1496a0a-9f18-46e0-8def-4684af42592c', 'b51a68f5-f0c3-4b2f-8faf-290dd560f642', 2, '26001271-e8bb-5f12-8b14-0ab1480a3865/7c1f42fd-b308-4449-bedc-10f9f336192d/8373be95-8b4b-4c07-ac4a-fddeb4e09565-002.jpg', '[{"bbox": [77, 50, 502, 82], "html": "<p><p>9. <math>y = (3x^2 + 1)^5</math></p></p>", "text": "9. y = (3x^2 + 1)^5", "label": "Equation"}, {"bbox": [155, 94, 401, 115], "html": "<p>Pakai chain rule</p>", "text": "Pakai chain rule", "label": "Text"}, {"bbox": [155, 113, 717, 176], "html": "<p><math display=\"block\">\\frac{dy}{dx} = 5 \\cdot (3x^2 + 1)^4 \\cdot 6x = 30x(3x^2 + 1)^4</math></p>", "text": "\\frac{dy}{dx} = 5 \\cdot (3x^2 + 1)^4 \\cdot 6x = 30x(3x^2 + 1)^4", "label": "Equation"}, {"bbox": [82, 212, 741, 277], "html": "<p><p>10. <math>u = \\ln(x)</math> <math>\\int_1^e \\frac{\\ln x}{x} = \\int_0^1 u \\, du \\cdot x</math><br/><math>du = 1/x</math></p></p>", "text": "10. u = \\ln(x) \\int_1^e \\frac{\\ln x}{x} = \\int_0^1 u \\, du \\cdot x\ndu = 1/x", "label": "Equation"}, {"bbox": [150, 276, 691, 346], "html": "<p><p>batas atas = <math>\\ln(e) = 1</math> <math>= \\int_0^1 u \\, du</math><br/>\n  batas bawah <math>\\ln(1) = 0</math></p></p>", "text": "batas atas = \\ln(e) = 1 = \\int_0^1 u \\, du\n batas bawah \\ln(1) = 0", "label": "Equation"}, {"bbox": [521, 343, 760, 400], "html": "<p><math display=\"block\">= \\left[ \\frac{u^2}{2} \\right]_0^1 = \\frac{1}{2}</math></p>", "text": "= \\left[ \\frac{u^2}{2} \\right]_0^1 = \\frac{1}{2}", "label": "Equation"}, {"bbox": [77, 436, 881, 504], "html": "<p>11. kawat 40cm, ukuran persegi agar luas maximum<br/>\n  kel persegi = <math>2(p+l) = 40</math></p>", "text": "11. kawat 40cm, ukuran persegi agar luas maximum\n kel persegi = 2(p+l) = 40", "label": "Text"}, {"bbox": [313, 504, 480, 553], "html": "<p><p><math>p+l = 20</math><br/><math>l = 20 - p</math></p></p>", "text": "p+l = 20\nl = 20 - p", "label": "Equation"}, {"bbox": [71, 564, 666, 671], "html": "<p><p>luas persegi = <math>p(20-p)</math><br/><math>= 20p - p^2 \\Rightarrow 20 - 2p = 0</math><br/><math>\\frac{20}{2p}</math> <math>20 = 2p</math><br/><math>p = 10</math></p></p>", "text": "luas persegi = p(20-p)\n= 20p - p^2 \\Rightarrow 20 - 2p = 0\n\\frac{20}{2p} 20 = 2p\np = 10", "label": "Equation"}, {"bbox": [102, 694, 467, 744], "html": "<p><p>akhirnya <math>p = 10</math><br/><math>l = 20 - 10 = 10</math></p></p>", "text": "akhirnya p = 10\nl = 20 - 10 = 10", "label": "Equation"}, {"bbox": [77, 787, 301, 811], "html": "<p>12. luas Kurva</p>", "text": "12. luas Kurva", "label": "Text"}, {"bbox": [97, 813, 197, 839], "html": "<p><p><math>y = x^2</math></p></p>", "text": "y = x^2", "label": "Equation"}, {"bbox": [118, 850, 227, 872], "html": "<p><p><math>y = x + 2</math></p></p>", "text": "y = x + 2", "label": "Equation"}, {"bbox": [118, 862, 451, 916], "html": "<p><p>luas = <math>\\int_{-1}^2 x^2 - x - 2 \\, dx</math></p></p>", "text": "luas = \\int_{-1}^2 x^2 - x - 2 \\, dx", "label": "Equation"}, {"bbox": [202, 922, 458, 969], "html": "<p><math display=\"block\">= \\left[ \\frac{1}{3}x^3 - \\frac{1}{2}x^2 - 2x \\right]_0^2</math></p>", "text": "= \\left[ \\frac{1}{3}x^3 - \\frac{1}{2}x^2 - 2x \\right]_0^2", "label": "Equation"}, {"bbox": [645, 781, 804, 802], "html": "<p>titik potong</p>", "text": "titik potong", "label": "Text"}, {"bbox": [617, 807, 813, 830], "html": "<p><p><math>\\Rightarrow x^2 = x + 2</math></p></p>", "text": "\\Rightarrow x^2 = x + 2", "label": "Equation"}, {"bbox": [688, 835, 862, 857], "html": "<p><p><math>x^2 - x - 2 = 0</math></p></p>", "text": "x^2 - x - 2 = 0", "label": "Equation"}, {"bbox": [712, 867, 878, 894], "html": "<p><p><math>(x-2)(x+1)</math></p></p>", "text": "(x-2)(x+1)", "label": "Equation"}, {"bbox": [750, 897, 878, 921], "html": "<p><p><math>x = (-1, 2)</math></p></p>", "text": "x = (-1, 2)", "label": "Equation"}]', 'success', NULL, '20