INSERT INTO public.test_pages (id, student_test_id, page_no, image_path, ocr_result, status, error, updated_at, created_at) VALUES ('be60e886-816a-55a1-b14d-fd9159f9e9db', '2a84cf4d-1851-5bde-897c-0455273b9710', 1, '9ceb48bd-1943-5673-bfa3-ae10632401e6/b105aeeb-e3f4-5b1b-95b5-d8b68d75b2bd/90150d22-dafc-5e40-b409-312c3fd87b5e/p1.jpg', '[{"bbox": [40, 300, 560, 480], "kind": "text", "text": "Jawaban nomor 1 ...", "page_no": 1, "block_id": "p1b1"}, {"bbox": [40, 520, 560, 700], "kind": "text", "text": "Jawaban nomor 2 ...", "page_no": 1, "block_id": "p1b2"}]', 'success', NULL, '2026-10-08 09:25:38.656532+00', '2026-10-08 09:25:38.656532+00');
INSERT INTO public.test_pages (id, student_test_id, page_no, image_path, ocr_result, status, error, updated_at, created_at) VALUES ('b1c7770e-2c71-4429-a5c0-bbf158149473', 'b51a68f5-f0c3-4b2f-8faf-290dd560f642', 3, '26001271-e8bb-5f12-8b14-0ab1480a3865/7c1f42fd-b308-4449-bedc-10f9f336192d/8373be95-8b4b-4c07-ac4a-fddeb4e09565-003.jpg', '[{"bbox": [56, 49, 271, 82], "html": "<p>lanjutan no 12</p>", "text": "lanjutan no 12", "label": "Text"}, {"bbox": [65, 74, 903, 215], "html": "<p><math display=\"block\">\\begin{aligned}\\left[ \\frac{1}{3}x^3 - \\frac{1}{2}x^2 - 2x \\right]_{-1}^2 &amp;= \\frac{1}{3}(8) - \\frac{1}{2}(4) - 2 - \\left( \\frac{1}{3} \\right) + \\frac{1}{2} - 1 \\\\ &amp;= \\left( \\frac{8}{3} - 2 - 4 \\right) - \\left( -\\frac{1}{3} - \\frac{1}{2} + 2 \\right) \\\\ &amp;= -\\frac{10}{3} - \\frac{7}{6} \\\\ &amp;= \\frac{9}{2} \\rightarrow \\text{positif karena luas tdk negatif}\\end{aligned}</math></p>", "text": "\\begin{aligned}\\left[ \\frac{1}{3}x^3 - \\frac{1}{2}x^2 - 2x \\right]_{-1}^2 &= \\frac{1}{3}(8) - \\frac{1}{2}(4) - 2 - \\left( \\frac{1}{3} \\right) + \\frac{1}{2} - 1 \\\\ &= \\left( \\frac{8}{3} - 2 - 4 \\right) - \\left( -\\frac{1}{3} - \\frac{1}{2} + 2 \\right) \\\\ &= -\\frac{10}{3} - \\frac{7}{6} \\\\ &= \\frac{9}{2} \\rightarrow \\text{positif karena luas tdk negatif}\\end{aligned}", "label": "Equation"}, {"bbox": [53, 233, 262, 260], "html": "<p><p>13. <math>f(x) = x^2</math></p></p>", "text": "13. f(x) = x^2", "label": "Equation"}, {"bbox": [117, 263, 262, 292], "html": "<p><p><math>f''(x) = 2x</math></p></p>", "text": "f''(x) = 2x", "label": "Equation"}, {"bbox": [139, 300, 721, 505], "html": "<p><math display=\"block\">\\begin{aligned}\\lim_{h \\rightarrow 0} \\frac{f(x+h) - f(x)}{h} &amp;= \\frac{x^2 + 2xh + h^2 - x^2}{h} \\\\ &amp;= \\frac{2xh + h^2}{h} \\\\ &amp;= 2x + h \\\\ &amp;= \\lim_{h \\rightarrow 0} 2x + h = 2x\\end{aligned}</math></p>", "text": "\\begin{aligned}\\lim_{h \\rightarrow 0} \\frac{f(x+h) - f(x)}{h} &= \\frac{x^2 + 2xh + h^2 - x^2}{h} \\\\ &= \\frac{2xh + h^2}{h} \\\\ &= 2x + h \\\\ &= \\lim_{h \\rightarrow 0} 2x + h = 2x\\end{aligned}", "label": "Equation"}, {"bbox": [53, 547, 232, 571], "html": "<p>14. buktikan</p>", "text": "14. buktikan", "label": "Text"}, {"bbox": [58, 578, 879, 608], "html": "<p>a) <math>x^3 + x - 1 \\rightarrow</math> tepat satu akan real dan berada di <math>(0,1)</math></p>", "text": "a) x^3 + x - 1 \\rightarrow tepat satu akan real dan berada di (0,1)", "label": "Text"}, {"bbox": [91, 608, 323, 632], "html": "<p><p><math>\\Rightarrow f(0) = -1 &lt; 0</math></p></p>", "text": "\\Rightarrow f(0) = -1 < 0", "label": "Equation"}, {"bbox": [134, 640, 319, 661], "html": "<p><p><math>f(1) = 1 &gt; 0</math></p></p>", "text": "f(1) = 1 > 0", "label": "Equation"}, {"bbox": [94, 672, 886, 727], "html": "<p>menurut teorema nilai antara, ada <math>c</math> diantara nilai <math>x = 0</math> dan <math>1</math></p>", "text": "menurut teorema nilai antara, ada c diantara nilai x = 0 dan 1", "label": "Text"}, {"bbox": [58, 736, 314, 760], "html": "<p>b) akan tepat 1</p>", "text": "b) akan tepat 1", "label": "Text"}, {"bbox": [106, 764, 775, 796], "html": "<p><p><math>f''(x) = 3x^2 + 1 \\geq 1 &gt; 0</math> untuk semua <math>x \\in \\mathbb{R}</math>.</p></p>", "text": "f''(x) = 3x^2 + 1 \\geq 1 > 0 untuk semua x \\in \\mathbb{R}.", "label": "Equation"}, {"bbox": [110, 824, 721, 858], "html": "<p>kesimpulan <math>\\Rightarrow</math> persamaan <math>x^3 + x - 1 = 0</math></p>", "text": "kesimpulan \\Rightarrow persamaan x^3 + x - 1 = 0", "label": "Text"}, {"bbox": [128, 863, 831, 895], "html": "<p>punya tepat 1 akan real dan terletak diantara</p>", "text": "punya tepat 1 akan real dan terletak diantara", "label": "Text"}, {"bbox": [130, 898, 377, 920], "html": "<p><math>x = 0</math> dan <math>x = 1</math></p>", "text": "x = 0 dan x = 1", "label": "Text"}]', 'success', NULL, '2026-10-14 10:34:09.305392+00', '2026-10-14 10:33:41.738423+00');
